#!/usr/bin/env python3
"""Build the static bilingual site: python3 tools/build.py. No dependencies."""
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
C=json.loads((ROOT/'content.json').read_text())
def e(s): return html.escape(str(s),quote=True)
def url(page,lang): return ('fa' if page=='home' and lang=='fa' else 'index' if page=='home' else page+('-fa' if lang=='fa' else ''))+'.html'
def a(page,label,lang,cls=''): return f'<a class="{cls}" href="{url(page,lang)}">{e(label)}</a>'
def heading(k,t,desc=''): return f'<div class="section-heading"><p class="eyebrow">{e(k)}</p><h2>{e(t)}</h2>'+ (f'<p class="lead">{e(desc)}</p>' if desc else '')+'</div>'
def cards(items,cls=''): return '<div class="cards '+cls+'">'+''.join(f'<article class="card"><span class="index">{i+1:02}</span><h3>{e(x[0])}</h3><p>{e(x[1])}</p></article>' for i,x in enumerate(items))+'</div>'
def placeholder(title,body,l): return f'<article class="placeholder"><span class="pill">{e(l["pending"])}</span><h3>{e(title)}</h3><p>{e(body)}</p></article>'
def cta(l,lang): return '<section class="cta wrap"><p class="eyebrow">'+e(l['ctaK'])+'</p><h2>'+e(l['ctaTitle'])+'</h2><p>'+e(l['ctaText'])+'</p>'+a('contact',l['consult'],lang,'button light')+'</section>'
def render(page,lang):
 l=C[lang]; fa=lang=='fa'; title=l['pages'][page]; current=url(page,lang); other=url(page,'en' if fa else 'fa')
 nav=''.join(a(k,l['pages'][k],lang,'active' if page==k else '') for k in ['approach','services','pathways','about','journal'])
 out=f'''<!doctype html><html lang="{lang}" dir="{'rtl' if fa else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | {e(l['brand'])}</title><meta name="description" content="{e(l['description'])}"><meta name="theme-color" content="#0b2232"><meta property="og:title" content="{e(title)} | Vellum House"><meta property="og:description" content="{e(l['description'])}"><meta property="og:type" content="website"><meta property="og:locale" content="{'fa_IR' if fa else 'en_GB'}"><link rel="alternate" hreflang="en" href="{url(page,'en')}"><link rel="alternate" hreflang="fa" href="{url(page,'fa')}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/config.js" defer></script><script src="assets/main.js" defer></script></head><body id="top"><a class="skip" href="#main">{e(l['skip'])}</a><div class="announcement">{e(l['announcement'])}</div><header class="header"><div class="nav-wrap"><a class="brand" href="{url('home',lang)}" aria-label="{e(l['brand'])}"><span class="monogram" aria-hidden="true">VH<span>✦</span></span><span>VELLUM HOUSE<small>{e(l['tag'])}</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">{e(l['menu'])} <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="{e(l['navLabel'])}">{nav}<a class="language" href="{other}" lang="{'en' if fa else 'fa'}" dir="{'ltr' if fa else 'rtl'}">{'English' if fa else 'فارسی'}</a>{a('contact',l['consult'],lang,'button compact')}</nav></div></header><main id="main">'''
 if page=='home':
  out+=f'''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">{e(l['heroK'])}</p><h1>{e(l['heroTitle'])}</h1><p class="hero-description">{e(l['heroText'])}</p><div class="actions">{a('contact',l['consult'],lang,'button')}{a('approach',l['explore'],lang,'text-link')}</div><p class="micro">{e(l['heroNote'])}</p></div><figure class="hero-art"><img src="assets/vh-brand.webp" width="1254" height="1254" alt="{e(l['logoAlt'])}" fetchpriority="high"><figcaption><span>VELLUM HOUSE</span><span>{e(l['artCaption'])}</span></figcaption></figure></section><div class="principles"><div class="wrap">'''+''.join('<span>'+e(x)+'</span>' for x in l['principles'])+'</div></div>'
  out+='<section class="section wrap intro"><p class="eyebrow">'+e(l['introK'])+'</p><div><h2>'+e(l['introTitle'])+'</h2><p class="lead">'+e(l['introText'])+'</p>'+a('approach',l['introLink'],lang,'text-link')+'</div></section>'
  out+='<section class="section tint"><div class="wrap">'+heading(l['servicesK'],l['servicesTitle'],l['servicesText'])+cards(l['serviceCards'][:3])+a('services',l['allServices'],lang,'text-link below')+'</div></section>'
  out+='<section class="section wrap">'+heading(l['pathK'],l['pathTitle'],l['pathText'])+'<div class="path-grid">'+''.join('<a class="path-card" href="'+url('pathways',lang)+'#path-'+str(i)+'"><span class="index">0'+str(i+1)+'</span><h3>'+e(x[0])+'</h3><p>'+e(x[1])+'</p><span class="text-link">'+e(l['learn'])+'</span></a>' for i,x in enumerate(l['pathCards']))+'</div></section>'
  out+='<section class="section dark"><div class="wrap roadmap-preview">'+heading(l['roadK'],l['roadTitle'],l['roadText'])+'<ol class="steps">'+''.join('<li><span class="index">0'+str(i+1)+'</span><div><h3>'+e(x[0])+'</h3><p>'+e(x[1])+'</p></div></li>' for i,x in enumerate(l['steps'][:3]))+'</ol>'+a('approach',l['fullRoad'],lang,'text-link gold')+'</div></section>'
  out+='<section class="section wrap statement"><span class="ornament" aria-hidden="true">✦</span><p class="eyebrow">'+e(l['beyondK'])+'</p><h2>'+e(l['beyondTitle'])+'</h2><p class="lead">'+e(l['beyondText'])+'</p></section>'
 elif page in ['approach','services','pathways','about','journal','contact','privacy','terms']:
  h=l['pageHeros'][page]
  out+='<section class="page-hero wrap"><p class="eyebrow">'+e(title)+'</p><h1>'+e(h[0])+'</h1><p class="lead">'+e(h[1])+'</p></section>'
  if page=='approach':
   out+='<section class="section wrap split"><div>'+heading(l['problemK'],l['problemTitle'])+'</div><div>'+''.join('<p class="lead">'+e(x)+'</p>' for x in l['problemText'])+'</div></section><section class="section tint"><div class="wrap">'+heading(l['roadK'],l['roadTitle'],l['roadText'])+'<ol class="roadmap">'+''.join('<li><span class="index">0'+str(i+1)+'</span><h3>'+e(x[0])+'</h3><p>'+e(x[1])+'</p></li>' for i,x in enumerate(l['steps']))+'</ol></div></section><section class="section wrap split"><div>'+heading(l['reportK'],l['reportTitle'],l['reportText'])+'</div><div class="report"><p class="eyebrow">'+e(l['reportLabel'])+'</p>'+''.join('<div class="report-row"><span>'+e(x[0])+'</span><strong>'+e(x[1])+'</strong></div>' for x in l['reportRows'])+'<p class="micro">'+e(l['reportNote'])+'</p></div></section>'
  elif page=='services':
   out+='<section class="section wrap">'+cards(l['serviceCards'],'services-grid')+'</section><section class="section tint"><div class="wrap split">'+heading(l['scopeK'],l['scopeTitle'],l['scopeText'])+'<div class="plain-list">'+''.join('<p>'+e(x)+'</p>' for x in l['scopePoints'])+'</div></div></section>'
  elif page=='pathways':
   for i,x in enumerate(l['pathDetails']):
    out+='<section id="path-'+str(i)+'" class="section '+('tint' if i%2==0 else '')+'"><div class="wrap split"><div><p class="eyebrow">0'+str(i+1)+'</p><h2>'+e(x[0])+'</h2><p class="lead">'+e(x[1])+'</p></div><div><ul class="check-list">'+''.join('<li>'+e(b)+'</li>' for b in x[2])+'</ul>'+a('contact',l['discussPath'],lang,'text-link')+'</div></div></section>'
  elif page=='about':
   out+='<section class="section wrap split"><div class="brand-panel"><img src="assets/vh-brand.webp" width="1254" height="1254" alt="'+e(l['logoAlt'])+'" loading="lazy"></div><div>'+heading(l['beliefK'],l['beliefTitle'])+''.join('<p class="lead">'+e(x)+'</p>' for x in l['beliefText'])+'</div></section><section class="section tint"><div class="wrap">'+heading(l['valuesK'],l['valuesTitle'])+cards(l['values'])+'</div></section><section class="section wrap">'+heading(l['teamK'],l['teamTitle'],l['teamText'])+'<div class="cards">'+placeholder(*l['founder'],l)+placeholder(*l['mentors'],l)+placeholder(*l['operations'],l)+'</div></section><section class="section tint"><div class="wrap">'+heading(l['storiesK'],l['storiesTitle'],l['storiesText'])+'<div class="cards two">'+placeholder(*l['storySlot'],l)+placeholder(*l['quoteSlot'],l)+'</div></div></section>'
  elif page=='journal':
   out+='<section class="section wrap"><div class="resource-feature"><div><p class="eyebrow">'+e(l['brochureK'])+'</p><h2>'+e(l['brochureTitle'])+'</h2><p>'+e(l['brochureText'])+'</p><a class="button" href="assets/Vellum_House_Brochure.pdf" download>'+e(l['download'])+'</a></div><div class="book" aria-hidden="true"><span>VH</span><strong>VELLUM<br>HOUSE</strong><small>PRIVATE ACADEMIC<br>MANAGEMENT</small></div></div></section><section class="section tint"><div class="wrap">'+heading(l['readingK'],l['readingTitle'],l['readingText'])+'<div class="cards">'+''.join(placeholder(*x,l) for x in l['articles'])+'</div></div></section>'
  elif page=='contact':
   out+='<section class="section wrap contact-grid"><div>'+heading(l['contactK'],l['contactTitle'],l['contactText'])+'<ol class="contact-steps">'+''.join('<li>'+e(x)+'</li>' for x in l['contactSteps'])+'</ol><div class="note"><strong>'+e(l['pricingTitle'])+'</strong><p>'+e(l['pricingText'])+'</p></div><a class="text-link" href="https://reyhanehvojoudi.ir/fa.html#vh-consultation">'+e(l['directLink'])+'</a></div><div class="form-card"><form id="inquiry-form"><h2>'+e(l['formTitle'])+'</h2><p class="micro">'+e(l['formIntro'])+'</p><div class="form-grid">'
   for field in l['fields']:
    key,label,typ,required=field
    out+='<div class="field '+('full' if typ=='textarea' else '')+'"><label for="'+key+'">'+e(label)+(' <span aria-hidden="true">*</span>' if required else ' <span class="optional">'+e(l['optional'])+'</span>')+'</label>'
    req=' required' if required else ''
    if typ=='textarea': out+='<textarea id="'+key+'" name="'+key+'" rows="4" maxlength="2500"'+req+'></textarea>'
    elif typ=='select': out+='<select id="'+key+'" name="'+key+'"'+req+'><option value="">'+e(l['choose'])+'</option>'+''.join('<option>'+e(v)+'</option>' for v in l['selects'][key])+'</select>'
    else: out+='<input id="'+key+'" name="'+key+'" type="'+typ+'" maxlength="200"'+(' autocomplete="email" dir="ltr"' if typ=='email' else ' autocomplete="name"' if key=='name' else '')+req+'>'
    out+='</div>'
   out+='</div><label class="consent"><input type="checkbox" name="consent" required><span>'+e(l['consent'])+' '+a('privacy',l['privacyLink'],lang)+'</span></label><button class="button" type="submit">'+e(l['prepare'])+'</button><p class="micro">'+e(l['noSubmit'])+'</p></form><section id="inquiry-result" hidden aria-live="polite"><h3 tabindex="-1" id="result-title">'+e(l['resultTitle'])+'</h3><p>'+e(l['resultText'])+'</p><textarea id="inquiry-summary" rows="12" readonly aria-label="'+e(l['summaryLabel'])+'"></textarea><div class="actions"><button class="button" id="copy-summary" type="button">'+e(l['copy'])+'</button><a class="button outline" id="send-inquiry" href="https://reyhanehvojoudi.ir/fa.html#vh-consultation">'+e(l['openContact'])+'</a></div><p id="copy-status" role="status"></p></section></div></section><section class="section tint"><div class="wrap faq-wrap">'+heading(l['faqK'],l['faqTitle'])+'<div class="faq">'+''.join('<details><summary>'+e(x[0])+'</summary><p>'+e(x[1])+'</p></details>' for x in l['faq'])+'</div></div></section>'
  elif page in ['privacy','terms']:
   out+='<section class="section wrap legal"><div class="note">'+e(l['policyNote'])+'</div>'+''.join('<section><h2>'+e(x[0])+'</h2><p>'+e(x[1])+'</p></section>' for x in l[page])+'</section>'
 if page not in ['contact','privacy','terms']: out+=cta(l,lang)
 out+='</main><footer><div class="wrap footer-grid"><div><a class="footer-brand" href="'+url('home',lang)+'">VELLUM HOUSE</a><p>'+e(l['footerText'])+'</p></div><div><p class="eyebrow">'+e(l['footerExplore'])+'</p>'+''.join(a(k,l['pages'][k],lang) for k in ['approach','services','pathways','about','journal'])+'</div><div><p class="eyebrow">'+e(l['footerStart'])+'</p>'+a('contact',l['consult'],lang)+'<a href="assets/Vellum_House_Brochure.pdf" download>'+e(l['download'])+'</a><a href="'+other+'" lang="'+('en' if fa else 'fa')+'">'+('English' if fa else 'فارسی')+'</a></div></div><div class="wrap footer-bottom"><span>© <span id="year">2026</span> Vellum House</span><div>'+a('privacy',l['pages']['privacy'],lang)+a('terms',l['pages']['terms'],lang)+'<a href="#top">'+e(l['backTop'])+'</a></div></div></footer></body></html>'
 (ROOT/current).write_text(out,encoding='utf-8')
for lang in ['en','fa']:
 for page in C[lang]['pages']: render(page,lang)
print('Built 18 pages in English and Persian.')
